    FeaturedListSync = apps.get_model("lists", "FeaturedListSync")
    CustomListItem = apps.get_model("lists", "CustomListItem")
    syncs = FeaturedListSync.objects.filter(custom_list__isnull=False).exclude(entry_notes={})
    for list_id, notes in syncs.values_list("custom_list_id", "entry_notes"):
        if not isinstance(notes, dict):
            continue
        rows = list(
            CustomListItem.objects.filter(
                custom_list_id=list_id,
                item_id__in=[int(key) for key in notes if str(key).isdigit()],
            ),
        )
        for row in rows:
            row.note = str(notes.get(str(row.item_id)) or "")[:200]
        CustomListItem.objects.bulk_update(rows, ["note"], batch_size=500)


